/* eslint-disable max-lines */

'use strict';

// MODULES //

var logger = require( 'debug' );
var join = require( '@stdlib/array/base/join' );
var lowercase = require( '@stdlib/string/lowercase' );
var replace = require( '@stdlib/string/replace' );
var format = require( '@stdlib/string/format' );
var classifyHTML = require( './classify_html.js' );
var createDirective = require( './directive.js' );
var plainText = require( './plain_text.js' );
var diagnostic = require( './diagnostic.js' );
var account = require( './account.js' );
var nodes = require( './nodes.js' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:convert' );
var SECTION_HEADINGS = {
	'usage': 'usage',
	'examples': 'examples',
	'notes': 'notes',
	'references': 'references',
	'related': 'see also',
	'c': 'c apis',
	'cli': 'cli'
};


// FUNCTIONS //

/**
* Returns a heading slug for a human-friendly semantic key.
*
* @private
* @param {string} text - heading text
* @returns {string} slug
*/
function slug( text ) {
	var value = replace( lowercase( text ), /[^a-z0-9]+/g, '-' );
	return replace( value, /^-|-$/g, '' ) || 'topic';
}

/**
* Initializes internal fields on a semantic container.
*
* @private
* @param {Object} node - semantic container
* @param {Array} roles - structural roles
* @param {string} semanticKey - human-friendly semantic key
* @returns {Object} semantic container
*/
function initialize( node, roles, semanticKey ) {
	// Internal fields carry traversal state shared by child constructors. They are removed after IDs and bottom-up hashes have been finalized...
	node.internal = {
		'counters': {},
		'roles': roles,
		'semanticKey': semanticKey,
		'javascriptCodes': 0,
		'seenRenderable': false,
		'headingDepth': null
	};
	debug( 'Initialized semantic container: id=%s type=%s semanticKey=%s roles=%s', node.id || 'document', node.type || 'document', semanticKey, join( roles, ',' ) );
	return node;
}

/**
* Tests whether a heading is the heading for a structural section.
*
* @private
* @param {Object} container - semantic section
* @param {Object} heading - source heading
* @returns {boolean} boolean indicating whether a heading belongs to the section
*/
function isSectionHeading( container, heading ) {
	var expected = SECTION_HEADINGS[ container.role ];

	// A section heading must be its first renderable content and one level below the section path. Later matching headings are content topics, not wrappers...
	if ( !expected || container.internal.seenRenderable ) {
		return false;
	}
	return (
		heading.depth === container.path.length+1 &&
		lowercase( plainText( heading ) ) === expected
	);
}

/**
* Tests whether a heading is a strong API entry candidate.
*
* @private
* @param {Object} heading - source heading
* @returns {boolean} boolean indicating whether a heading is an API entry candidate
*/
function isAPIEntryHeading( heading ) {
	// Restrict API candidates to call signatures such as `foo( x )` or `namespace.foo( x )`; descriptive headings should remain generic topics:
	return /^[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*\s*\([^)]*\)$/.test( plainText( heading ) );
}

/**
* Returns a topic role.
*
* @private
* @param {Object} container - semantic container
* @param {Object} heading - source heading
* @param {Object} state - conversion state
* @returns {string} topic role
*/
function topicRole( container, heading, state ) {
	// Tutorial headings define either major document sections or nested instructional steps...
	if ( state.options.profile === 'tutorial' ) {
		return ( heading.depth === 2 ) ? 'tutorial-section' : 'tutorial-step';
	}
	// API entry semantics only apply to signature-like topics nested beneath a usage section...
	if ( container.internal.roles.indexOf( 'usage' ) >= 0 && isAPIEntryHeading( heading ) ) {
		return 'api-entry-candidate';
	}
	return 'generic';
}

/**
* Returns the current topic target.
*
* @private
* @param {Object} container - semantic container
* @param {Array} topics - topic stack
* @returns {Object} semantic target
*/
function target( container, topics ) {
	// Content belongs to the deepest currently open heading topic, falling back to the structural section/document when no topic is active:
	return ( topics.length ) ? topics[ topics.length-1 ] : container;
}

/**
* Tests whether an MDAST node is a standalone image paragraph.
*
* @private
* @param {Object} node - MDAST node
* @returns {boolean} boolean indicating whether a node is an image paragraph
*/
function isImageParagraph( node ) {
	return (
		node.type === 'paragraph' &&
		node.children.length === 1 &&
		(
			node.children[ 0 ].type === 'image' ||
			node.children[ 0 ].type === 'imageReference'
		)
	);
}

/**
* Creates a topic for a heading.
*
* @private
* @param {Object} container - semantic section
* @param {Array} topics - topic stack
* @param {Object} mdast - source heading
* @param {Object} state - conversion state
* @returns {Object} semantic topic
*/
function topic( container, topics, mdast, state ) {
	var semanticKey;
	var parent;
	var out;
	var key;
	var o;

	// A heading at the same or shallower depth closes preceding topics. What remains on the stack is the semantic parent for the new topic...
	while (
		topics.length &&
		topics[ topics.length-1 ].internal.headingDepth >= mdast.depth
	) {
		topics.pop();
	}
	parent = target( container, topics );
	key = slug( plainText( mdast ) );
	semanticKey = format( '%s/%s', parent.internal.semanticKey, key );

	// Topic grouping is synthesized from heading hierarchy, hence its transformed provenance, while the heading itself remains a normal semantic child...
	o = {
		'type': 'topic',
		'id': nodes.allocate( parent, 'topic' ),
		'semanticKey': semanticKey,
		'role': topicRole( container, mdast, state ),
		'headingRef': null,
		'children': [],
		'source': state.provenance.source( [ mdast ], 'topic-group' )
	};
	out = initialize( o, parent.internal.roles, semanticKey );
	out.internal.headingDepth = mdast.depth;
	out.children.push( nodes.heading( out, mdast, state ) );
	out.headingRef = out.children[ 0 ].id;

	parent.children.push( out );
	topics.push( out );
	debug( 'Created semantic topic: id=%s role=%s depth=%d parent=%s', out.id, out.role, mdast.depth, parent.id || 'document' );

	return out;
}

/**
* Creates a semantic structural section.
*
* @private
* @param {Object} structural - internal structural section
* @param {Object} state - conversion state
* @returns {Object} semantic section
*/
function section( structural, state ) {
	var semanticKey;
	var roles;
	var mdast;
	var out;
	var o;

	mdast = [ structural.openingNode ];
	roles = structural.parent.path.concat( structural.role );
	semanticKey = join( roles, '/' );

	// Section provenance includes every wrapper node that established or recovered the boundary. Content provenance remains attached to descendant nodes...
	if ( structural.closingNode ) {
		mdast.push( structural.closingNode );
	}
	if ( structural.endNode ) {
		mdast.push( structural.endNode );
	}
	o = {
		'type': 'section',
		'id': structural.id,
		'semanticKey': semanticKey,
		'role': structural.role,
		'path': roles,
		'ordinal': structural.ordinal,
		'headingRef': null,
		'children': [],
		'empty': false,
		'recovered': structural.recovered,
		'source': state.provenance.source( mdast, 'section-structure' )
	};
	out = initialize( o, roles, semanticKey );
	debug( 'Created semantic section: id=%s role=%s recovered=%s', out.id, out.role, out.recovered );
	return out;
}

/**
* Reports and clears orphan immediate directives.
*
* @private
* @param {Object} state - conversion state
* @param {Array} pending - pending immediate directives
* @returns {void}
*/
function orphanDirectives( state, pending ) {
	var directive;

	if ( pending.length === 0 ) {
		return;
	}
	debug( 'Resolving orphan directives: count=%d', pending.length );

	// Directive comments cannot cross a non-code semantic boundary. Report and drain them so they are never applied to an unrelated later code block...
	while ( pending.length ) {
		directive = pending.shift();
		debug( 'Reporting orphan directive: id=%s family=%s', directive.id, directive.family );
		diagnostic( state, 'warning', 'orphan-directive', 'Immediate directive is not attached to a code block.', state.directiveNodes[ directive.id ], {
			'directiveRef': directive.id
		});
	}
}

/**
* Reports and clears unattached equation metadata.
*
* @private
* @param {Object} state - conversion state
* @param {(Object|null)} pending - pending equation metadata
* @param {Object} parent - semantic parent
* @returns {null} null
*/
function orphanEquation( state, pending, parent ) {
	var out;

	if ( pending ) {
		// Preserve unmatched metadata as raw HTML. This keeps permissive conversion lossless while making the malformed equation sequence visible...
		debug( 'Preserving orphan equation metadata as raw flow: parent=%s', parent.id || 'document' );
		out = nodes.raw( parent, pending.node, 'orphan-equation-wrapper', state );
		parent.children.push( out );
		diagnostic( state, 'warning', 'malformed-equation-wrapper', 'Equation wrapper is not followed by a math fence.', pending.node );
	}
	return null;
}

/**
* Creates and records a directive resource.
*
* @private
* @param {Object} state - conversion state
* @param {Object} mdast - source HTML node
* @param {Object} classification - directive classification
* @returns {Object} directive resource
*/
function directive( state, mdast, classification ) {
	var record;
	var out;

	// Store directives outside canonical flow, but retain both the original node and accounting record so a later code cell can add itself as a target...
	out = createDirective( state, mdast, classification );
	state.document.resources.directives.push( out );
	state.directiveNodes[ out.id ] = mdast;

	record = account( state, mdast, 'consumed-as-metadata', classification.type, 'Stored as a directive resource.', [ out.id ] );
	state.directiveAccounting[ out.id ] = record;
	debug( 'Recorded directive resource: id=%s family=%s', out.id, out.family );

	return out;
}

/**
* Processes a source heading.
*
* @private
* @param {Object} container - semantic container
* @param {Array} topics - topic stack
* @param {Object} mdast - source heading
* @param {Object} state - conversion state
* @returns {void}
*/
function heading( container, topics, mdast, state ) {
	var expectedDepth;
	var out;

	debug( 'Processing heading: depth=%d container=%s', mdast.depth, container.id || 'document' );
	state.lastRootWasTitle = false;

	// A characterized section heading belongs directly to the section and becomes its heading reference; it must not introduce a redundant topic container...
	if ( container.type === 'section' && isSectionHeading( container, mdast ) ) {
		out = nodes.heading( container, mdast, state );
		container.children.push( out );
		container.headingRef = out.id;
		container.internal.seenRenderable = true;
		debug( 'Attached structural section heading: heading=%s section=%s', out.id, container.id );
		return;
	}
	if ( container.type === 'section' ) {
		expectedDepth = container.path.length + 1;

		// Same-level or shallower headings violate the expected wrapper hierarchy. Preserve their location directly instead of fabricating a nested topic...
		if ( mdast.depth <= expectedDepth ) {
			topics.length = 0; // close active topics in order to prevent later prose being appended beneath an earlier topic and violating source order
			out = nodes.heading( container, mdast, state );
			container.children.push( out );
			container.internal.seenRenderable = true;
			diagnostic( state, 'info', 'heading-hierarchy', 'Heading does not match the expected structural section hierarchy.', mdast, {
				'headingRef': out.id,
				'actualDepth': mdast.depth,
				'expectedMinimumDepth': expectedDepth+1
			});
			registerTitle( out, mdast, state, false );
			debug( 'Preserved out-of-hierarchy section heading: heading=%s section=%s', out.id, container.id );
			return;
		}
		// Deeper headings define topic groups scoped to this structural section:
		topic( container, topics, mdast, state );
		container.internal.seenRenderable = true;
		return;
	}
	// Tutorial documents use ordinary Markdown heading hierarchy instead of HTML section wrappers. Group every root heading below the title into a topic container...
	if ( state.options.profile === 'tutorial' && mdast.depth > 1 ) {
		topic( container, topics, mdast, state );
		container.internal.seenRenderable = true;
		return;
	}
	out = nodes.heading( container, mdast, state );
	container.children.push( out );

	// Only root-level flow participates in title/summary recognition:
	registerTitle( out, mdast, state, true );
}

/**
* Registers a level-one heading as a title candidate.
*
* @private
* @param {Object} heading - semantic heading
* @param {Object} mdast - source heading
* @param {Object} state - conversion state
* @param {boolean} summaryCandidate - boolean indicating whether a root summary may follow
* @returns {void}
*/
function registerTitle( heading, mdast, state, summaryCandidate ) {
	// Non-H1 headings cannot define the canonical document title...
	if ( mdast.depth !== 1 ) {
		return;
	}
	if ( state.document.titleRef === null ) {
		// `lastRootWasTitle` is deliberately adjacency-based: only the immediately following root block quote qualifies as the document summary...
		state.document.titleRef = heading.id;
		state.titleNode = mdast;
		state.lastRootWasTitle = summaryCandidate;
		debug( 'Registered document title: heading=%s summaryCandidate=%s', heading.id, summaryCandidate );
		return;
	}
	debug( 'Encountered duplicate document title: heading=%s selected=%s', heading.id, state.document.titleRef );
	diagnostic( state, 'error', 'duplicate-title', 'Document contains more than one level-one heading.', mdast, {
		'titleRef': state.document.titleRef,
		'duplicateRef': heading.id
	});
}

/**
* Processes a raw HTML source node.
*
* @private
* @param {Object} container - semantic container
* @param {Array} topics - topic stack
* @param {Object} mdast - source HTML node
* @param {Object} context - container conversion context
* @param {Object} state - conversion state
* @returns {void}
*/
function html( container, topics, mdast, context, state ) {
	var classification;
	var dest;
	var key;
	var out;

	classification = classifyHTML( mdast.value );
	key = join( state.provenance.path( mdast ), '.' );
	debug( 'Processing standalone HTML: path=%s classification=%s container=%s', key, classification.type, container.id || 'document' );

	// Structural recovery may override normal HTML classification when a malformed wrapper must be preserved verbatim in canonical flow...
	if ( state.forceRaw[ key ] ) {
		classification = {
			'type': state.forceRaw[ key ]
		};
	}
	if ( state.options.profile === 'generic' ) {
		// The generic profile assigns no special meaning to document HTML conventions. Flush adjacent Markdown before emitting each standalone raw block...
		context.flush();
		dest = target( container, topics );
		out = nodes.raw( dest, mdast, classification.type, state );
		dest.children.push( out );
		container.internal.seenRenderable = true;
		debug( 'Preserved standalone HTML for generic profile: node=%s classification=%s', out.id, classification.type );
		return;
	}
	if ( classification.type === 'run' || classification.type === 'run-disable' || classification.type === 'eslint' ) {
		// Treat a directive comment as a metadata boundary and retain it for the immediately following code block...
		context.flush();
		out = directive( state, mdast, classification );
		context.pendingDirectives.push( out );
		debug( 'Queued directive for next code block: id=%s pending=%d', out.id, context.pendingDirectives.length );
		return;
	}
	// Any other standalone HTML breaks adjacency for immediate directives and pending Markdown, so settle both before processing the classification:
	context.flush();
	orphanDirectives( state, context.pendingDirectives );
	if ( classification.type === 'equation-fallback' || classification.type === 'equation-close' ) {
		// Rendered equation fallback is maintenance markup only when it immediately follows a recognized math fence. Otherwise preserve it as unmatched raw HTML...
		if ( context.equationSequence ) {
			debug( 'Discarding generated equation fallback markup: classification=%s', classification.type );
			account( state, mdast, 'discarded-maintenance', classification.type, 'Removed characterized equation fallback markup.', [] );
			if ( classification.type === 'equation-close' ) {
				context.equationSequence = false;
			}
			return;
		}
		classification = {
			'type': format( 'unmatched-%s', classification.type )
		};
	}
	context.equationSequence = false;
	dest = target( container, topics );
	if ( classification.type !== 'equation-open' ) {
		// A pending equation-open comment is valid only when the next semantic item is a math fence; other HTML first turns it into an orphan raw node...
		context.equation = orphanEquation( state, context.equation, dest );
	}
	if ( classification.type === 'equation-open' ) {
		// Delay emission until the following node reveals whether this metadata can enrich a math node or must be preserved as malformed raw content...
		context.equation = orphanEquation( state, context.equation, dest );
		context.equation = {
			'node': mdast,
			'label': classification.label,
			'alt': classification.alt
		};
		debug( 'Queued equation metadata for next math fence: label=%s', classification.label || 'none' );
		return;
	}
	if ( classification.type === 'license' ) {
		// The core converter records the source license disposition but intentionally does not promote package/license metadata into the semantic document:
		account( state, mdast, 'consumed-as-metadata', 'license', 'Recorded source license markup in source accounting.', [] );
		debug( 'Consumed document license markup as source metadata.' );
		return;
	}
	if (
		classification.type === 'maintenance-comment' ||
		classification.type === 'related-links-marker' ||
		classification.type === 'links-marker'
	) {
		// These characterized comments support document maintenance and have no reader-visible semantic value:
		account( state, mdast, 'discarded-maintenance', classification.type, 'Removed characterized document maintenance markup.', [] );
		debug( 'Discarded document maintenance markup: classification=%s', classification.type );
		return;
	}
	// Unknown and intentionally preserved malformed HTML remains explicit raw flow:
	dest = target( container, topics );
	out = nodes.raw( dest, mdast, classification.type, state );
	dest.children.push( out );
	debug( 'Preserved standalone HTML as raw flow: node=%s classification=%s', out.id, classification.type );

	container.internal.seenRenderable = true;
}

/**
* Appends a semantic node for a standalone special Markdown block.
*
* @private
* @param {Object} mdast - source MDAST node
* @param {Object} parent - semantic parent
* @param {Object} container - current semantic container
* @param {Object} state - conversion state
* @returns {void}
*/
function appendSpecialBlock( mdast, parent, container, state ) {
	var out;

	// The caller limits input to the two special root/block constructs supported by the semantic schema; all other MDAST blocks remain projected Markdown...
	if ( mdast.type === 'thematicBreak' ) {
		out = nodes.thematicBreak( parent, mdast, state );
	} else {
		out = nodes.frontmatter( parent, mdast, state );
	}
	parent.children.push( out );
	debug( 'Appended special block: node=%s sourceType=%s parent=%s', out.id, mdast.type, parent.id || 'document' );
	if ( mdast.type !== 'thematicBreak' ) {
		container.internal.seenRenderable = true;
	}
}

/**
* Converts the direct source children of a structural container.
*
* @private
* @param {Object} structural - internal structural container
* @param {Object} container - semantic container
* @param {Object} state - conversion state
* @returns {void}
*/
function convertContainer( structural, container, state ) {
	var pendingDirectives;
	var markdown;
	var equation;
	var context;
	var topics;
	var child;
	var dest;
	var out;
	var i;

	pendingDirectives = [];
	markdown = [];
	equation = null;
	topics = [];
	debug( 'Converting structural container: id=%s type=%s sourceChildren=%d', container.id || 'document', container.type, structural.rawChildren.length );

	// Track each kind of pending context separately: Markdown blocks coalesce, topics follow heading depth, all directive comments apply only to the immediately following code block, and equation metadata applies only to the immediately following math fence...
	context = {
		'pendingDirectives': pendingDirectives,
		'equation': equation,
		'equationSequence': false,
		'flush': flush
	};
	for ( i = 0; i < structural.rawChildren.length; i++ ) {
		child = structural.rawChildren[ i ];
		dest = target( container, topics );
		context.equation = equation;

		// Only adjacent HTML may form the post-math fallback sequence...
		if ( child.type !== 'html' ) {
			context.equationSequence = false;
		}
		if ( child.type === 'section' && child.rawChildren ) {
			// A nested structural boundary closes pending flow state. Convert its contents recursively, then derive whether the resulting section is empty...
			flush();
			orphanDirectives( state, pendingDirectives );
			equation = orphanEquation( state, equation, dest );
			topics.length = 0;
			out = section( child, state );
			container.children.push( out );
			container.internal.seenRenderable = true;
			convertContainer( child, out, state );
			out.empty = out.children.length === 0;
			debug( 'Converted nested structural section: id=%s children=%d empty=%s', out.id, out.children.length, out.empty );
			continue;
		}
		if ( child.type === 'definition' ) {
			// Definitions were collected before conversion and do not occupy canonical flow. This pass supplies their source-accounting disposition...
			flush();
			orphanDirectives( state, pendingDirectives );
			equation = orphanEquation( state, equation, dest );
			account( state, child, 'moved-to-resource', 'definition', 'Moved link definition to ordered resources.', [ state.definitionNodes[ join( state.provenance.path( child ), '.' ) ] ] );
			continue;
		}
		if ( child.type === 'html' ) {
			// HTML processing may update delayed equation state through the shared context object, so synchronize the local variable afterward...
			context.equation = equation;
			html( container, topics, child, context, state );
			equation = context.equation;
			state.lastRootWasTitle = false;
			continue;
		}
		if ( child.type === 'heading' ) {
			// Headings are hard grouping boundaries for prose, directives, equations, and the topic stack maintained by `heading`...
			flush();
			orphanDirectives( state, pendingDirectives );
			equation = orphanEquation( state, equation, dest );
			heading( container, topics, child, state );
			continue;
		}
		if (
			container.type === 'document' &&
			child.type === 'blockquote' &&
			state.lastRootWasTitle &&
			state.document.summaryRef === null
		) {
			// The first root block quote immediately following the title is promoted from generic Markdown to the canonical summary node...
			flush();
			out = nodes.summary( container, child, state );
			container.children.push( out );
			state.document.summaryRef = out.id;
			state.lastRootWasTitle = false;
			debug( 'Registered document summary: node=%s', out.id );
			continue;
		}
		state.lastRootWasTitle = false;
		if ( isImageParagraph( child ) ) {
			// A standalone image has enough structure for a first-class media node; images mixed with prose remain in projected Markdown...
			flush();
			orphanDirectives( state, pendingDirectives );
			equation = orphanEquation( state, equation, dest );
			dest.children.push( nodes.media( dest, child, state ) );
			container.internal.seenRenderable = true;
			continue;
		}
		if ( child.type === 'code' ) {
			flush();
			dest = target( container, topics );
			if ( child.lang && lowercase( child.lang ) === 'math' ) {
				// Math fences consume optional equation metadata and begin a short HTML fallback sequence whose generated markup may be discarded safely...
				orphanDirectives( state, pendingDirectives );
				out = nodes.math( dest, child, equation, state );
				if ( equation ) {
					account( state, equation.node, 'transformed', 'equation-wrapper', 'Attached equation metadata to semantic math node.', [
						out.id
					]);
				}
				equation = null;
				context.equationSequence = true;
				debug( 'Converted math fence: node=%s label=%s', out.id, out.label || 'none' );
			} else {
				// Attach each contiguous directive comment to this code block and then clear the pending list so that no directive affects a later standalone block...
				equation = orphanEquation( state, equation, dest );
				out = nodes.code( dest, child, pendingDirectives, state );
				pendingDirectives.length = 0;
				debug( 'Converted code block: node=%s language=%s role=%s', out.id, out.language || 'none', out.role );
			}
			dest.children.push( out );
			container.internal.seenRenderable = true;
			continue;
		}
		orphanDirectives( state, pendingDirectives );
		equation = orphanEquation( state, equation, dest );
		if ( child.type === 'thematicBreak' || child.type === 'yaml' ) {
			// These root/block constructs have dedicated semantic forms and therefore cannot be coalesced with adjacent projected Markdown...
			flush();
			dest = target( container, topics );
			appendSpecialBlock( child, dest, container, state );
			continue;
		}
		// All remaining MDAST blocks are accumulated into one contiguous Markdown unit, preserving order while avoiding a semantic node per paragraph/list:
		markdown.push( child );
		container.internal.seenRenderable = true;
	}
	flush();
	orphanDirectives( state, pendingDirectives );
	dest = target( container, topics );

	// Resolve any state left at the end of this structural container:
	orphanEquation( state, equation, dest );
	debug( 'Converted structural container: id=%s children=%d', container.id || 'document', container.children.length );

	/**
	* Flushes pending Markdown to the current semantic target.
	*
	* @private
	* @returns {void}
	*/
	function flush() {
		var current;

		if ( markdown.length === 0 ) {
			return;
		}
		// Resolve the target at flush time: an intervening heading may have changed the active topic since the buffer was initialized...
		current = target( container, topics );
		debug( 'Flushing Markdown blocks: target=%s count=%d', current.id || 'document', markdown.length );
		current.children.push( nodes.markdown( current, markdown, state ) );
		markdown = [];
	}
}


// MAIN //

/**
* Converts an internal structural tree to semantic document flow.
*
* @private
* @param {Object} structural - internal structural tree
* @param {Object} state - conversion state
* @returns {void}
*/
function convert( structural, state ) {
	debug( 'Converting structural tree to semantic flow...' );

	// The document uses the same internal container protocol as sections/topics, allowing node allocation and flow conversion to share one implementation:
	initialize( state.document, [], 'document' );
	state.document.type = 'document';
	convertContainer( structural, state.document, state );

	// Profile requirements are diagnostics rather than parser failures so that permissive callers still receive a complete semantic representation...
	if ( state.options.profile !== 'generic' && state.document.titleRef === null ) {
		diagnostic( state, 'error', 'missing-title', 'Document profile requires a level-one title heading.' );
	}
	if ( state.options.profile !== 'generic' && state.document.summaryRef === null ) {
		diagnostic( state, 'warning', 'missing-summary', 'Document profile expects a summary blockquote immediately after the title.' );
	}
	debug( 'Converted structural tree to semantic flow: children=%d title=%s summary=%s', state.document.children.length, state.document.titleRef || 'none', state.document.summaryRef || 'none' );
}


// EXPORTS //

module.exports = convert;
